package net.officefloor.hq.app.statement;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class StatementController {

    /**
     * A person's statements as the screen shows them: how many, and the last one's due-total (null for n/a) and
     * date.
     */
    public record StatementView(Long personId, int count, String dueTotal, LocalDate date) {
        static StatementView of(StatementService.Summary s) {
            if (s.last() == null) {
                return new StatementView(s.personId(), 0, null, null);
            }
            return new StatementView(s.personId(), s.count(),
                    s.last().getDueTotal() == null ? null : s.last().getDueTotal().toPlainString(),
                    s.last().getDate());
        }
    }

    /** What a statement is taken with: the date it is taken as of (null or missing: now). */
    public record TakeRequest(LocalDate asOf) {
    }

    /** A statement just taken, with all the person's claims as it left them. */
    public record TakenView(StatementView statement, List<ClaimView> claims) {
    }

    private final StatementService service;
    private final ClaimService claims;

    public StatementController(StatementService service, ClaimService claims) {
        this.service = service;
        this.claims = claims;
    }

    /** Each person's statements on the sheet, for the people who have any. */
    @GetMapping("/statements")
    public List<StatementView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.list(sheetId).stream().map(StatementView::of).toList();
    }

    @PostMapping("/people/{personId}/statement")
    public TakenView take(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long personId, @RequestBody(required = false) TakeRequest request,
            @SessionAttribute(SessionController.USER) String user) {
        LocalDate asOf = request == null ? null : request.asOf();
        StatementView taken = StatementView.of(service.take(user, sheetId, personId, asOf));
        List<ClaimView> theirs = claims.list(sheetId).stream().filter(c -> c.getPersonId().equals(personId))
                .map(ClaimView::of).toList();
        return new TakenView(taken, theirs);
    }

    /** Cancels the person's last statement; answers with their statements and claims as it left them. */
    @DeleteMapping("/people/{personId}/statement")
    public TakenView cancel(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long personId, @SessionAttribute(SessionController.USER) String user) {
        StatementView left = StatementView.of(service.cancel(user, sheetId, personId));
        List<ClaimView> theirs = claims.list(sheetId).stream().filter(c -> c.getPersonId().equals(personId))
                .map(ClaimView::of).toList();
        return new TakenView(left, theirs);
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A statement taken for a person: their due-total then (null for n/a), how many claims counted, when, and the date it
 * was taken as of (null: now).
 */
@Entity
@Table(name = "statement")
public class Statement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "due_total", precision = 14, scale = 2)
    private BigDecimal dueTotal;

    @Column(name = "claim_count", nullable = false)
    private int claimCount;

    /** The sheet's today when the statement was taken. */
    @Column(name = "taken_on", nullable = false)
    private LocalDate takenOn;

    /** The date the statement was taken as of; null for one taken now. */
    @Column(name = "as_of")
    private LocalDate asOf;

    /** The place the statement stands at in its person's order; null for its own id. */
    @Column(name = "place")
    private Long place;

    protected Statement() {
    }

    public Statement(String sheetId, Long personId, BigDecimal dueTotal, int claimCount, LocalDate takenOn,
            LocalDate asOf) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.dueTotal = dueTotal;
        this.claimCount = claimCount;
        this.takenOn = takenOn;
        this.asOf = asOf;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** The place the statement stands at in its person's order: the one it was given, else its id. */
    public long getPlace() {
        return place != null ? place : id;
    }

    /** Moves the statement to the person on the sheet, standing at the place in their order. */
    public void moveTo(String sheetId, Long personId, long place) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.place = place;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }

    public int getClaimCount() {
        return claimCount;
    }

    public LocalDate getTakenOn() {
        return takenOn;
    }

    public LocalDate getAsOf() {
        return asOf;
    }

    /** The statement's date: the date it was taken as of, else the sheet's today when it was taken. */
    public LocalDate getDate() {
        return asOf != null ? asOf : takenOn;
    }
}
package net.officefloor.hq.app.statement;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface StatementRepository extends JpaRepository<Statement, Long> {

    /** The sheet's statements, each person's in their order. */
    @Query("SELECT s FROM Statement s WHERE s.sheetId = ?1 ORDER BY COALESCE(s.place, s.id), s.id")
    List<Statement> findBySheetIdInOrder(String sheetId);

    /** The person's statements in their order: the last is their last statement. */
    @Query("SELECT s FROM Statement s WHERE s.sheetId = ?1 AND s.personId = ?2 ORDER BY COALESCE(s.place, s.id), s.id")
    List<Statement> findBySheetIdAndPersonIdInOrder(String sheetId, Long personId);
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The statements taken for the people on a sheet. */
@Service
public class StatementService {

    /** A person's statements: how many have been taken, and the last one (null with none). */
    public record Summary(Long personId, int count, Statement last) {
    }

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateChain rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final SettingsService settings;
    private final Audit audit;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            ClaimService claimService, RateChain rates, SheetService sheets, RollupService rollup,
            SettingsService settings, Audit audit) {
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    /** Each person's statements on the sheet, for the people who have any. */
    @Transactional(readOnly = true)
    public List<Summary> list(String sheetId) {
        Map<Long, Summary> by = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdInOrder(sheetId)) {
            Summary was = by.get(s.getPersonId());
            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
        }
        return List.copyOf(by.values());
    }

    /**
     * Takes a statement for the person, now (as of null) or as of a date on or before the sheet's today: see
     * {@link #take(String, String, Long)} and {@link #takeAsOf}.
     */
    @Transactional
    public Summary take(String by, String sheetId, Long personId, LocalDate asOf) {
        return asOf == null ? take(by, sheetId, personId) : takeAsOf(by, sheetId, personId, asOf);
    }

    /**
     * Takes a statement for the person: records their due-total now (late charges included) and binds each of their claims that counts to
     * the figure it has now; a claim that does not count (as an open one dated within a hold, or a deferred one) is freed (live again).
     */
    @Transactional
    public Summary take(String by, String sheetId, Long personId) {
        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Sheet sheet = sheets.load(sheetId);
        LocalDate today = sheet.getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        // the grades whose rate today decides n/a: the one in force today and each counted claim's
        Set<String> grades = new HashSet<>();
        grades.add(person.gradeOn(today));
        int count = 0;
        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            if (!person.countsLive(c, today)) {
                c.unbind();
                continue;
            }
            // a settled or already bound claim keeps its figure even with no rate in force today
            grades.add(person.gradeOn(c.getDate()));
            kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
            // the statement binds the rate figure under the late charge and the floor; both keep following the sheet
            BigDecimal due = claimService.due(sheetId, person, c);
            c.bind(claimService.figure(sheetId, person, c));
            count++;
            if (due != null) {
                kept = true;
                total = total.add(due);
            }
        }
        claims.flush();
        // as on screen: with no rate in force today for any of those grades and no claim with a figure, the due-total
        // is n/a
        boolean current = grades.stream().anyMatch(g -> rates.findInForce(sheetId, g, today).isPresent());
        // held to the sheet's cap, as on screen
        BigDecimal dueTotal = current || kept ? sheet.capped(total) : null;
        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, count, today, null));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + by + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
        rollup.recordChanges(by, sheetId, before);
        return new Summary(personId, statements.findBySheetIdAndPersonIdInOrder(sheetId, personId).size(),
                taken);
    }

    /**
     * Takes a statement for the person as of a date on or before the sheet's today. Their claims that counted at the
     * end of that date are bound to their figures as they stood then: only the changes made while the sheet's today
     * was on or before the date count (each claim's status, the rates, grades, settings, holds and retirement, and
     * the binding of the person's last statement), and the date stands in for the sheet's today in every figure. Each
     * other claim of theirs is freed, as a statement does. Refused for a date after the sheet's today, and for a
     * person added after it.
     */
    private Summary takeAsOf(String by, String sheetId, Long personId, LocalDate asOf) {
        Person current = people.findWithLockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Sheet sheet = sheets.load(sheetId);
        LocalDate today = sheet.getToday();
        if (asOf.isAfter(today)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A statement cannot be taken as of a date after the sheet's today.");
        }
        if (!current.addedBy(asOf)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person was not on the sheet on that date.");
        }
        Sheet then = sheet.asOf(asOf);
        Person person = current.asOf(asOf);
        List<RateChain.Tier> tiersThen = rates.tiersAsOf(sheetId, asOf);
        List<Rate> ratesThen = tiersThen.get(tiersThen.size() - 1).rates();
        // the binding of the person's last statement counts when it was taken while the sheet's today was on or before
        List<Statement> theirs = statements.findBySheetIdAndPersonIdInOrder(sheetId, personId);
        boolean bindingCounts = !theirs.isEmpty() && !theirs.get(theirs.size() - 1).getTakenOn().isAfter(asOf);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        Set<String> grades = new HashSet<>();
        grades.add(person.gradeOn(asOf));
        int count = 0;
        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            ClaimStatus status = c.statusAtEndOf(asOf);
            boolean bound = bindingCounts && c.isStated() && status != ClaimStatus.PENDING;
            boolean counts = status != null && status.counts() && !c.isDeferredAsOf(asOf)
                    && !(status.isOpen() && !bound && (person.getHolds().stream().anyMatch(h -> h.covers(c.getDate()))
                    || person.isRetiredOn(asOf)));
            if (!counts) {
                c.unbind();
                continue;
            }
            grades.add(person.gradeOn(c.getDate()));
            BigDecimal figure;
            BigDecimal due;
            if (status == ClaimStatus.SETTLED) {
                // its due as fixed then
                figure = c.dueLoggedAtEndOf(asOf);
                due = figure;
                kept = true;
            } else {
                figure = bound ? c.getStatedDue() : rateFigure(RateChain.forMark(tiersThen, c.getAddedMark()), then,
                        person.gradeOn(c.getDate()), c);
                kept |= bound && figure != null;
                due = ClaimService.liveDue(figure, c, person, then, status.isOpen());
            }
            c.bind(figure);
            count++;
            if (due != null) {
                kept = true;
                total = total.add(due);
            }
        }
        claims.flush();
        boolean inForce = grades.stream().anyMatch(g -> inForce(ratesThen, g, asOf) != null);
        BigDecimal dueTotal = inForce || kept ? then.capped(total) : null;
        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, count, today, asOf));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + by + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count
                + " asof=" + asOf);
        rollup.recordChanges(by, sheetId, before);
        return new Summary(personId, statements.findBySheetIdAndPersonIdInOrder(sheetId, personId).size(),
                taken);
    }

    /** The grade's rate in force on the date among the rates; null with none. */
    private static Rate inForce(List<Rate> rates, String grade, LocalDate date) {
        return Rate.inForce(rates.stream().filter(r -> r.getGrade().equals(grade)).toList(), date);
    }

    /**
     * The claim's rate figure among the rates, on the sheet as it stood: at the rate the grade has in force on its
     * date, rounded as the sheet decides for it; null (n/a) with none.
     */
    private static BigDecimal rateFigure(List<Rate> rates, Sheet sheet, String grade, Claim claim) {
        Rate rate = inForce(rates, grade, claim.getDate());
        return rate == null ? null
                : ClaimService.dueOn(claim.getAmount(), rate.getPct(), sheet.roundingOn(claim.getRoundsOn()));
    }

    /**
     * A steward cancels the person's last statement: the claims it bound are live again (a figure an earlier
     * statement bound is not restored), and the statement before it is the last. Refused unless the user is a
     * steward, and for a person with no statement. Returns the person's statements as the cancel left them.
     */
    @Transactional
    public Summary cancel(String by, String sheetId, Long personId) {
        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (!settings.isSteward(sheetId, by)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement.");
        }
        List<Statement> theirs = statements.findBySheetIdAndPersonIdInOrder(sheetId, personId);
        if (theirs.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is no statement to cancel.");
        }
        Statement last = theirs.get(theirs.size() - 1);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            if (c.isStated()) {
                c.unbind();
            }
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
        rollup.recordChanges(by, sheetId, before);
        int count = theirs.size() - 1;
        return new Summary(personId, count, count == 0 ? null : theirs.get(count - 1));
    }
}
-- Whether a claim is bound by its person's last statement, and the figure it is bound to (null for n/a).
-- A bound claim shows and totals that figure until the person's next statement rebinds or frees it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

-- The statements taken for a person, in the order taken (by id): the due-total then (null for n/a),
-- the count of claims that counted and the sheet's today when it was taken.
CREATE TABLE statement (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id   BIGINT         NOT NULL REFERENCES person (id),
    due_total   DECIMAL(14, 2),
    claim_count INT            NOT NULL,
    taken_on    DATE           NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
-- A statement may be taken as of a date on or before the sheet's today (null: taken now). Every change it reads back
-- carries the sheet's today it was made on (made_on), so a statement as of a date counts only the changes made while
-- the sheet's today was on or before it. A null made_on is a change made before this was kept: it always counts.
ALTER TABLE statement ADD COLUMN as_of DATE;

-- The sheet's today when the person was added, and when their retirement date was set.
ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_on DATE;

ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;

-- The sheet's today when the claim was deferred.
ALTER TABLE claim ADD COLUMN deferred_on DATE;

-- Every rate set on a sheet, in the order set (by id): the grade, its from- and to-date, the percent, and the sheet's
-- today then. The rate a grade had for a from-date as of a date is the last one set for it on or before that date.
CREATE TABLE rate_change (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)    NOT NULL,
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(7, 2) NOT NULL,
    made_on   DATE
);
CREATE INDEX rate_change_sheet ON rate_change (sheet_id, id);
INSERT INTO rate_change (sheet_id, grade, from_date, to_date, pct, made_on)
    SELECT sheet_id, grade, from_date, to_date, pct, NULL FROM rate ORDER BY id;

-- Every value recorded for a dated setting of a sheet, in the order recorded (pos), with the sheet's today then.
CREATE TABLE sheet_setting_change (
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    pos           INT          NOT NULL,
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(30),
    made_on       DATE,
    PRIMARY KEY (sheet_id, pos)
);
INSERT INTO sheet_setting_change (sheet_id, pos, setting_key, from_date, setting_value, made_on)
    SELECT sheet_id, ROW_NUMBER() OVER (PARTITION BY sheet_id ORDER BY setting_key, from_date) - 1, setting_key,
           from_date, setting_value, NULL FROM sheet_setting;
-- A person's statements are in the order taken (by id), except those that came with another person merged into
-- them: those stand before the person's own, so the person's last statement stays theirs. The place a statement
-- stands at in its person's order; null for its own id.
ALTER TABLE statement ADD COLUMN place BIGINT;
