    public List<String> lineage(String sheetId) {
        List<String> ids = new ArrayList<>(List.of(sheetId));
        String at = sheetId;
        while (ids.size() <= LEVELS_UP) {
            String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
